// Reine JS-Implementierung von SHA-256/HMAC-SHA256 — keine Node-Module (require
// ist im n8n-Task-Runner-Sandbox verboten), kein Buffer/TextEncoder-Fallback nötig.
function utf8Bytes(str) {
  const bytes = [];
  for (let i = 0; i < str.length; i++) {
    let code = str.codePointAt(i);
    if (code > 0xffff) i++;
    if (code < 0x80) {
      bytes.push(code);
    } else if (code < 0x800) {
      bytes.push(0xc0 | (code >> 6), 0x80 | (code & 0x3f));
    } else if (code < 0x10000) {
      bytes.push(0xe0 | (code >> 12), 0x80 | ((code >> 6) & 0x3f), 0x80 | (code & 0x3f));
    } else {
      bytes.push(
        0xf0 | (code >> 18),
        0x80 | ((code >> 12) & 0x3f),
        0x80 | ((code >> 6) & 0x3f),
        0x80 | (code & 0x3f),
      );
    }
  }
  return bytes;
}

function sha256(bytes) {
  const K = [
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2,
  ];
  let H = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const l = bytes.length;
  const withOne = bytes.concat([0x80]);
  while (withOne.length % 64 !== 56) withOne.push(0);
  const bitLen = l * 8;
  for (let i = 7; i >= 0; i--) withOne.push(Math.floor(bitLen / Math.pow(2, i * 8)) & 0xff);
  function rotr(x, n) { return (x >>> n) | (x << (32 - n)); }
  for (let chunk = 0; chunk < withOne.length; chunk += 64) {
    const w = new Array(64).fill(0);
    for (let i = 0; i < 16; i++) {
      w[i] = ((withOne[chunk+i*4]<<24)|(withOne[chunk+i*4+1]<<16)|(withOne[chunk+i*4+2]<<8)|(withOne[chunk+i*4+3])) >>> 0;
    }
    for (let i = 16; i < 64; i++) {
      const s0 = rotr(w[i-15],7) ^ rotr(w[i-15],18) ^ (w[i-15]>>>3);
      const s1 = rotr(w[i-2],17) ^ rotr(w[i-2],19) ^ (w[i-2]>>>10);
      w[i] = (w[i-16] + s0 + w[i-7] + s1) >>> 0;
    }
    let [a,b,c,d,e,f,g,h] = H;
    for (let i = 0; i < 64; i++) {
      const S1 = rotr(e,6) ^ rotr(e,11) ^ rotr(e,25);
      const ch = (e & f) ^ (~e & g);
      const temp1 = (h + S1 + ch + K[i] + w[i]) >>> 0;
      const S0 = rotr(a,2) ^ rotr(a,13) ^ rotr(a,22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const temp2 = (S0 + maj) >>> 0;
      h=g; g=f; f=e; e=(d+temp1)>>>0; d=c; c=b; b=a; a=(temp1+temp2)>>>0;
    }
    H = [H[0]+a,H[1]+b,H[2]+c,H[3]+d,H[4]+e,H[5]+f,H[6]+g,H[7]+h].map(x=>x>>>0);
  }
  return H.map(x => x.toString(16).padStart(8, "0")).join("");
}

function hexToBytes(hex) {
  const out = [];
  for (let i = 0; i < hex.length; i += 2) out.push(parseInt(hex.substr(i, 2), 16));
  return out;
}

function hmacSha256Hex(keyStr, msgStr) {
  let key = utf8Bytes(keyStr);
  if (key.length > 64) key = hexToBytes(sha256(key));
  while (key.length < 64) key.push(0);
  const opad = key.map((b) => b ^ 0x5c);
  const ipad = key.map((b) => b ^ 0x36);
  const inner = hexToBytes(sha256(ipad.concat(utf8Bytes(msgStr))));
  return sha256(opad.concat(inner));
}

// Prüft die HMAC-SHA256-Signatur des eingehenden Webhook-Requests und
// normalisiert die Eingabefelder für die folgenden Nodes.
const secret = $env.PLANTAPP_WEBHOOK_SECRET;
if (!secret) {
  throw new Error('PLANTAPP_WEBHOOK_SECRET ist nicht gesetzt (n8n-Umgebungsvariable fehlt)');
}

const item = $input.item;
const headers = item.json.headers || {};
const body = item.json.body || {};

const timestamp = headers['x-plantapp-timestamp'];
const signature = headers['x-plantapp-signature'];
const rawBody = JSON.stringify(body);

if (!timestamp || !signature) {
  throw new Error('Fehlende Signatur-Header');
}

const age = Date.now() - Number(timestamp);
if (!Number.isFinite(age) || age < 0 || age > 5 * 60 * 1000) {
  throw new Error('Zeitstempel ungültig oder zu alt (Replay-Schutz)');
}

const expected = hmacSha256Hex(secret, `${timestamp}.${rawBody}`);
if (expected !== signature) {
  throw new Error('Signatur ungültig');
}

return {
  json: {
    jobId: body.jobId,
    query: body.query,
    locale: body.locale || 'de',
    hardinessZone: body.hardinessZone ?? null,
    callbackUrl: body.callbackUrl,
    schemaVersion: body.schemaVersion,
    promptVersion: body.promptVersion || null,
  },
};

// Baut den Prompt für die AI (Gemini) aus der recherchierten Pflanze.
// WICHTIG: Der Prompt beschreibt exakt das CareProfile-JSON-Schema aus
// packages/shared/src/care-profile.ts — bei Schema-Änderungen im Code
// diesen Text mit aktualisieren.

const schema = "{\n  \"identity\": { \"botanicalName\": string, \"commonNamesDe\": string[]|null, \"commonNamesEn\": string[]|null, \"family\": string|null, \"cultivar\": string|null },\n  \"placement\": { \"light\": \"full_sun\"|\"partial_sun\"|\"bright_indirect\"|\"shade\"|null, \"indoor\": boolean|null, \"outdoor\": boolean|null, \"recommendedDirection\": (\"N\"|\"NE\"|\"E\"|\"SE\"|\"S\"|\"SW\"|\"W\"|\"NW\")[]|null, \"humidityMinPct\": number|null, \"humidityMaxPct\": number|null, \"temperatureMinC\": number|null, \"temperatureOptimalC\": number|null, \"temperatureMaxC\": number|null, \"hardy\": boolean|null, \"hardyToC\": number|null, \"winterProtection\": string|null } | null,\n  \"water\": { \"intervalDaysBySeason\": { \"spring\": number|null, \"summer\": number|null, \"autumn\": number|null, \"winter\": number|null } | null, \"amount\": string|null, \"method\": string|null, \"letTopLayerDryOut\": boolean|null } | null,\n  \"soil\": { \"substrate\": string|null, \"phMin\": number|null, \"phMax\": number|null, \"drainage\": string|null } | null,\n  \"fertilizer\": { \"npk\": string|null, \"rhythm\": string|null, \"seasonWindow\": string[]|null } | null,\n  \"pruning\": { \"windows\": [{ \"type\": \"shape\"|\"thinning\"|\"rejuvenation\"|\"deadheading\", \"months\": string[] }] | null } | null,\n  \"repotting\": { \"everyYears\": number|null, \"bestMonths\": string[]|null } | null,\n  \"bloom\": { \"months\": string[]|null, \"color\": string|null, \"fragrant\": boolean|null, \"deadheadSpentBlooms\": boolean|null } | null,\n  \"harvest\": { \"months\": string[]|null } | null,\n  \"propagation\": { \"methods\": string[]|null, \"bestMonths\": string[]|null } | null,\n  \"toxicity\": { \"petsToxic\": boolean|null, \"petNotes\": string|null, \"childrenToxic\": boolean|null, \"childrenNotes\": string|null } | null,\n  \"size\": { \"heightMinCm\": number|null, \"heightMaxCm\": number|null, \"widthMinCm\": number|null, \"widthMaxCm\": number|null, \"growthRate\": \"slow\"|\"medium\"|\"fast\"|null } | null,\n  \"problems\": [{ \"name\": string, \"symptoms\": string|null, \"remedy\": string|null }] | null,\n  \"meta\": { \"confidence\": { [section: string]: number } | null, \"sources\": string[]|null, \"model\": string|null, \"schemaVersion\": number, \"promptVersion\": string|null }\n}";

const query = $json.query;

const prompt = `Du bist ein Experte für Pflanzenpflege. Recherchiere fundierte, corrente Pflegeinformationen für folgende Pflanze und antworte AUSSCHLIESSLICH mit einem einzigen validen JSON-Objekt, das exakt diesem Schema entspricht (kein Markdown, kein Fließtext davor oder danach):

${schema}

Pflanze: "${query}"

Regeln:
- Alle Textfelder (amount, method, substrate, drainage, npk, rhythm, winterProtection, notes, problems, months, color) auf Deutsch.
- botanicalName bleibt lateinisch.
- Wenn ein Wert nicht mit ausreichender Sicherheit bekannt ist: null verwenden, NICHT raten oder erfinden.
- meta.sources: liste die tatsächlich verwendeten Quellen (URLs), falls über Websuche verfügbar; sonst leeres Array.
- meta.schemaVersion muss genau ${$json.schemaVersion} sein.
- Gib NUR das JSON-Objekt zurück, keinen weiteren Text.`;

return {
  json: {
    ...$json,
    prompt,
  },
};

// Parst die Gemini-Antwort, validiert grob die Struktur und baut die
// Callback-Nutzlast. Bei Fehlern wird stattdessen {jobId, error} gebaut,
// damit der Job in plantapp sauber als "failed" markiert wird statt ewig
// "queued" zu bleiben.

const jobId = $('Signatur prüfen & normalisieren').item.json.jobId;

let payload;
try {
  const candidates = $json.candidates || [];
  const text = candidates[0]?.content?.parts?.map(p => p.text).join('') || '';
  const cleaned = text.trim().replace(/^```json/i, '').replace(/^```/, '').replace(/```$/, '').trim();
  const result = JSON.parse(cleaned);

  if (!result || typeof result !== 'object' || !result.identity || !result.identity.botanicalName) {
    throw new Error('Antwort enthält kein gültiges CareProfile (identity.botanicalName fehlt)');
  }

  payload = { jobId, result };
} catch (err) {
  payload = { jobId, error: 'AI-Antwort konnte nicht geparst werden: ' + err.message };
}

return { json: payload };

