// Signiert die Callback-Nutzlast mit demselben HMAC-Schema wie der
// eingehende Webhook-Request.
const secret = $env.PLANTAPP_WEBHOOK_SECRET;
const callbackUrl = $('Signatur prüfen & normalisieren').item.json.callbackUrl;

const bodyString = JSON.stringify($json);
const timestamp = Date.now().toString();
const signature = hmacSha256Hex(secret, `${timestamp}.${bodyString}`);

return {
  json: {
    callbackUrl,
    bodyString,
    timestamp,
    signature,
  },
};
